using Jotunn.Configs;
using UnityEngine;

namespace BrudvikWhiteHilt.Items.Foraging.Vivianite;

/// <summary>
/// Vivianite, grey-blue nodules in the wet moss of the Mistlands that turn deeper blue in the air; ground, it is a blue
/// paint. Model: generated by AssetSource/Tools/make_forage_models.py.
/// </summary>
public class Vivianite : ForageableBase
{
    /// <summary>
    /// Prefab name of the vivianite item.
    /// </summary>
    public const string PrefabName = "WhiteHiltVivianite";

    /// <inheritdoc/>
    public override string BaseName => PrefabName;

    /// <inheritdoc/>
    protected override string FullName => "Vivianite";

    /// <inheritdoc/>
    protected override string Description => "Grey-blue nodules dug from the wet moss. They darken to a deep blue in the air, and ground fine they colour paint.";

    /// <inheritdoc/>
    protected override string CopyItemFrom => "Flint";

    /// <inheritdoc/>
    protected override string CopyPickableFrom => "Pickable_Stone";

    /// <inheritdoc/>
    protected override VegetationConfig Vegetation => new()
    {
        Biome = Heightmap.Biome.Mistlands,
        // Groups per zone where the ground suits it; the generator keeps trying spots until they are placed.
        Min = 1,
        Max = 1,
        ForcePlacement = true,
        GroupSizeMin = 1,
        GroupSizeMax = 2,
        GroupRadius = 3f,
        MinAltitude = 1f,
        MaxTilt = 20f,
        ScaleMin = 0.85f,
        ScaleMax = 1.15f,
        BlockCheck = true
    };

    /// <inheritdoc/>
    public override bool Enabled => true;

    /// <inheritdoc/>
    protected override string ExtraDropFrom => null;

    /// <inheritdoc/>
    protected override float DefaultGroundClearance => 0.05f;

    /// <inheritdoc/>
    protected override void ApplyVisual(GameObject visualRoot)
    {
        ReplacePlantMesh(visualRoot, IsItem(visualRoot) ? "vivianitelump" : "vivianite", 0.07f);
    }
}
